import json
with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for p in data.get('projects',[]):
        name = p['path'].rsplit('/',1)[-1] if '/' in p['path'] else p['path'].rsplit('\\\\',1)[-1]
        for fw in p.get('frameworks',[]):
            for pkg in fw.get('topLevelPackages',[]):
                key = (name, pkg['id'])
                result[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion','?'))
    return result

b = extract(baseline)
a = extract(after)

print('CHANGES:')
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key)
    av = a.get(key)
    if bv != av:
        print(f'  {key[0]} | {key[1]} | {bv} -> {av}')

print()
print('UNCHANGED:')
for key in sorted(b.keys()):
    if b.get(key) == a.get(key):
        print(f'  {key[0]} | {key[1]} | {b[key]}')
"

